            st.trailers = pairs.items;
        }
        const frame = switch (Codec.statusFrame(self.alloc, wire.frameTrailers, stream_id, st)) {
            .bytes => |f| f,
            .status => return,
        };
        self.emit(wire.frameTrailers, stream_id, frame[Codec.header_len..]);
        self.alloc.free(frame);
    }

    fn readerLoop(self: *Http2Transport) void {
        var chunk: [65536]u8 = undefined;
        while (!self.closed) {
            var fds = [_]std.posix.pollfd{.{ .fd = self.stream.handle, .events = std.posix.POLL.IN, .revents = 0 }};
            const ready = std.posix.poll(&fds, 100) catch break;
            if (self.closed) break;
            if (ready == 0) continue;
            const n = self.stream.read(&chunk) catch break;
            if (n == 0) break;
            self.recv_buffer.appendSlice(self.alloc, chunk[0..n]) catch break;
            while (self.recv_buffer.items.len >= 9) {
                const items = self.recv_buffer.items;
                const len = (@as(usize, items[0]) << 16) | (@as(usize, items[1]) << 8) | items[2];
                if (items.len < 9 + len) break;
                const frame_type = items[3];
                const flags = items[4];
                const stream_id = (@as(u32, items[5] & 0x7f) << 24) | (@as(u32, items[6]) << 16) | (@as(u32, items[7]) << 8) | items[8];
                const payload = self.alloc.dupe(u8, items[9 .. 9 + len]) catch return;
                const rest = self.alloc.dupe(u8, items[9 + len ..]) catch {
                    self.alloc.free(payload);
                    return;
                };
                self.recv_buffer.clearRetainingCapacity();
                self.recv_buffer.appendSlice(self.alloc, rest) catch {};
                self.alloc.free(rest);
                self.onFrame(frame_type, flags, stream_id, payload);
                self.alloc.free(payload);
            }
        }
        self.markClosed();
        self.queue_mutex.lock();
        self.queue_closed = true;
        self.queue_cond.broadcast();
        self.queue_mutex.unlock();
    }

    fn markClosed(self: *Http2Transport) void {
        self.flow_mutex.lock();
        self.closed = true;
        self.flow_cond.broadcast();
        self.flow_mutex.unlock();
    }

    fn onFrame(self: *Http2Transport, frame_type: u8, flags: u8, stream_id: u32, payload: []const u8) void {
        switch (frame_type) {
            h2_settings => {
                if ((flags & flag_ack) != 0) return;
                var new_initial = self.peer_initial_window;
                var off: usize = 0;
                while (off + 6 <= payload.len) : (off += 6) {
                    const ident = (@as(u16, payload[off]) << 8) | payload[off + 1];
                    const value: i64 = (@as(i64, payload[off + 2]) << 24) | (@as(i64, payload[off + 3]) << 16) | (@as(i64, payload[off + 4]) << 8) | payload[off + 5];
                    if (ident == 0x3) new_initial = value;
                }
                const delta = new_initial - self.peer_initial_window;
                self.peer_initial_window = new_initial;
                if (delta != 0) {
                    self.flow_mutex.lock();
                    var it = self.stream_windows.valueIterator();
                    while (it.next()) |v| v.* += delta;
                    self.flow_cond.broadcast();
                    self.flow_mutex.unlock();
                }
                self.writeFrame(h2_settings, flag_ack, 0, "") catch {};
            },
            h2_window_update => {
                if (payload.len >= 4) {
                    const inc: i64 = (@as(i64, payload[0] & 0x7f) << 24) | (@as(i64, payload[1]) << 16) | (@as(i64, payload[2]) << 8) | payload[3];
                    self.flow_mutex.lock();
                    if (stream_id == 0) {
                        self.conn_window += inc;
                    } else {
                        const cur = self.stream_windows.get(stream_id) orelse self.peer_initial_window;
                        self.stream_windows.put(stream_id, cur + inc) catch {};
                    }
                    self.flow_cond.broadcast();
                    self.flow_mutex.unlock();
                }
            },
            h2_ping => {
                if ((flags & flag_ack) == 0 and payload.len == 8) {
                    self.writeFrame(h2_ping, flag_ack, 0, payload) catch {};
                }
            },
            h2_rst_stream => {
                self.emit(wire.frameRst, stream_id, "{\"code\":8,\"message\":\"rst stream\"}");
            },
            h2_headers, h2_continuation => {
                const entry = self.header_blocks.getOrPut(stream_id) catch return;
                if (!entry.found_existing) entry.value_ptr.* = .empty;
                entry.value_ptr.appendSlice(self.alloc, payload) catch return;
                if ((flags & flag_end_headers) != 0) {
                    const block = entry.value_ptr.toOwnedSlice(self.alloc) catch return;
                    defer self.alloc.free(block);
                    _ = self.header_blocks.remove(stream_id);
                    self.onHeaders(stream_id, (flags & flag_end_stream) != 0, block);
                }
            },
            h2_data => {
                var body = payload;
                if ((flags & flag_padded) != 0 and body.len >= 1) {
                    const pad: usize = body[0];
                    body = if (pad + 1 <= body.len) body[1 .. body.len - pad] else body[0..0];
                }
                if (body.len > 0) {
                    var wu: [4]u8 = undefined;
                    writeWindowUpdate(&wu, body.len);
                    self.writeFrame(h2_window_update, 0, 0, &wu) catch {};
                    self.writeFrame(h2_window_update, 0, stream_id, &wu) catch {};
                    const entry = self.data_buffers.getOrPut(stream_id) catch return;
                    if (!entry.found_existing) entry.value_ptr.* = .empty;
                    entry.value_ptr.appendSlice(self.alloc, body) catch return;
                    self.drainMessages(stream_id);
                }
                if ((flags & flag_end_stream) != 0) {
                    self.emitTrailersFrame(stream_id, 2, "missing grpc-status", null);
                }
            },
            else => {},
        }
    }

    fn writeWindowUpdate(out: *[4]u8, increment: usize) void {
        out[0] = @intCast((increment >> 24) & 0x7f);
        out[1] = @intCast((increment >> 16) & 0xff);
        out[2] = @intCast((increment >> 8) & 0xff);
        out[3] = @intCast(increment & 0xff);
    }

    fn onHeaders(self: *Http2Transport, stream_id: u32, end_stream: bool, block: []const u8) void {
        var headers: std.ArrayList([2][]u8) = .empty;
        defer {
            for (headers.items) |e| {
                self.alloc.free(e[0]);
                self.alloc.free(e[1]);
            }
            headers.deinit(self.alloc);
        }
        self.decoder.decode(self.alloc, block, &headers) catch return;
        var metadata = std.StringHashMap([]const u8).init(self.alloc);
        defer metadata.deinit();
        // metadata values borrow the decoded header slices, which
        // outlive this call until the deferred free above; the
        // emit helpers serialize immediately.
        var status: ?[]const u8 = null;
        var message: ?[]const u8 = null;
        for (headers.items) |h| {
            const name = h[0];
            const value = h[1];
            if (std.mem.eql(u8, name, "grpc-status")) {
                status = value;
            } else if (std.mem.eql(u8, name, "grpc-message")) {
                message = value;
            } else if (std.mem.eql(u8, name, "grpc-encoding")) {
                if (std.mem.eql(u8, value, "gzip")) {
                    self.decompress_in.put(stream_id, {}) catch {};
                }
            } else if (std.mem.startsWith(u8, name, ":") or std.mem.eql(u8, name, "content-type") or std.mem.eql(u8, name, "grpc-accept-encoding")) {
                // transport-owned: not metadata
            } else if (!metadata.contains(name)) {
                metadata.put(name, value) catch {};
            }
        }
        const first = !self.headers_seen.contains(stream_id);
        self.headers_seen.put(stream_id, {}) catch {};
        if (end_stream and status != null) {
            const code = std.fmt.parseInt(i32, status.?, 10) catch 2;
            const decoded = percentDecode(self.alloc, message orelse "");
            defer if (decoded) |d| self.alloc.free(d);
            self.emitTrailersFrame(stream_id, code, decoded orelse "", &metadata);
        } else if (first) {
            self.emitHeadersFrame(stream_id, &metadata);
            if (end_stream) {
                self.emitTrailersFrame(stream_id, 2, "missing grpc-status", &metadata);
            }
        } else if (end_stream) {
            self.emitTrailersFrame(stream_id, 2, "missing grpc-status", &metadata);
        }
    }

    fn drainMessages(self: *Http2Transport, stream_id: u32) void {
        const buf = self.data_buffers.getPtr(stream_id) orelse return;
        var off: usize = 0;
        while (buf.items.len - off >= 5) {
            const data = buf.items;
            const mlen = (@as(usize, data[off + 1]) << 24) | (@as(usize, data[off + 2]) << 16) | (@as(usize, data[off + 3]) << 8) | data[off + 4];
            if (data.len - off - 5 < mlen) break;
            const compressed = data[off] & 0xff;
            const raw = data[off + 5 .. off + 5 + mlen];
            off += 5 + mlen;
            if (compressed == 1 or self.decompress_in.contains(stream_id)) {
                const plain = gunzip(self.alloc, raw) catch continue;
                defer self.alloc.free(plain);
                self.emit(wire.frameData, stream_id, plain);
            } else {
                self.emit(wire.frameData, stream_id, raw);
            }
        }
        if (off > 0) {
            const rest = self.alloc.dupe(u8, buf.items[off..]) catch return;
            buf.clearRetainingCapacity();
            buf.appendSlice(self.alloc, rest) catch {};
            self.alloc.free(rest);
        }
    }

    fn percentDecode(alloc: std.mem.Allocator, value: []const u8) ?[]u8 {
        var out: std.ArrayList(u8) = .empty;
        var i: usize = 0;
        while (i < value.len) {
            const c = value[i];
            if (c == '%' and i + 2 < value.len) {
                const hi = hexDigit(value[i + 1]);
                const lo = hexDigit(value[i + 2]);
                if (hi >= 0 and lo >= 0) {
                    out.append(alloc, @intCast((hi << 4) | lo)) catch return null;
                    i += 3;
                    continue;
                }
            }
            out.append(alloc, c) catch return null;
            i += 1;
        }
        return out.toOwnedSlice(alloc) catch null;
    }

    fn hexDigit(c: u8) i32 {
        return switch (c) {
            '0'...'9' => c - '0',
            'a'...'f' => c - 'a' + 10,
            'A'...'F' => c - 'A' + 10,
            else => -1,
        };
    }

    fn sendFn(ctx: *anyopaque, data: []const u8) anyerror!void {
        const self: *Http2Transport = @ptrCast(@alignCast(ctx));
        try self.handleSend(data);
    }

    fn handleSend(self: *Http2Transport, message: []const u8) !void {
        const frame = switch (Codec.decodeFrame(message)) {
            .frame => |f| f,
            .status => |st| {
                if (st.code != wire.codeOk) return error.BadFrame;
                return;
            },
        };
        const stream_id = frame.stream_id;
        const payload = frame.payload;
        switch (frame.type) {
            wire.frameHeaders => {
                var headers = switch (Codec.parseHeaders(self.alloc, payload)) {
                    .headers => |h| h,
                    .status => return error.BadFrame,
                };
                defer Codec.freeHeaders(self.alloc, &headers);
                self.flow_mutex.lock();
                if (!self.stream_windows.contains(stream_id)) {
                    self.stream_windows.put(stream_id, self.peer_initial_window) catch {};
                }
                self.flow_mutex.unlock();
                if (headers.metadata.get("grpc-encoding")) |enc| {
                    if (std.mem.eql(u8, enc, "gzip")) {
                        self.compress_out.put(stream_id, {}) catch {};
                    }
                }
                var block: std.ArrayList(u8) = .empty;
                defer block.deinit(self.alloc);
                try block.append(self.alloc, 0x83); // :method: POST
                try block.append(self.alloc, if (std.mem.eql(u8, self.scheme, "https")) @as(u8, 0x87) else @as(u8, 0x86)); // :scheme
                try writeLiteralIndexedName(&block, self.alloc, 4, headers.path orelse ""); // :path
                try writeLiteralIndexedName(&block, self.alloc, 1, self.authority); // :authority
                try writeLiteralIndexedName(&block, self.alloc, 31, "application/grpc");
                try writeLiteralNewName(&block, self.alloc, "grpc-accept-encoding", "gzip,identity");
                try writeLiteralNewName(&block, self.alloc, "te", "trailers");
                var it = headers.metadata.iterator();
                while (it.next()) |entry| {
                    var lower_buf: [256]u8 = undefined;
                    const key_src = entry.key_ptr.*;
                    if (key_src.len > lower_buf.len) continue;
                    for (key_src, 0..) |ch, idx| lower_buf[idx] = std.ascii.toLower(ch);
                    const key = lower_buf[0..key_src.len];
                    if (std.mem.eql(u8, key, "grpc-encoding")) {
                        try writeLiteralNewName(&block, self.alloc, key, "gzip");
                    } else {
                        try writeLiteralNewName(&block, self.alloc, key, entry.value_ptr.*);
                    }
                }
                try self.writeFrame(h2_headers, flag_end_headers, stream_id, block.items);
            },
            wire.frameData => {
                const compressed = self.compress_out.contains(stream_id);
                const body = if (compressed) try gzip(self.alloc, payload) else payload;
                defer if (compressed) self.alloc.free(body);
                var wire_buf: std.ArrayList(u8) = .empty;
                defer wire_buf.deinit(self.alloc);
                try wire_buf.append(self.alloc, if (compressed) @as(u8, 1) else @as(u8, 0));
                var len_buf: [4]u8 = undefined;
                std.mem.writeInt(u32, &len_buf, @intCast(body.len), .big);
                try wire_buf.appendSlice(self.alloc, &len_buf);
                try wire_buf.appendSlice(self.alloc, body);
                const bytes = wire_buf.items;
                var sent: usize = 0;
                while (sent < bytes.len) {
                    var allowance: usize = 0;
                    self.flow_mutex.lock();
                    while (!self.closed and (self.conn_window <= 0 or (self.stream_windows.get(stream_id) orelse self.peer_initial_window) <= 0)) {
                        self.flow_cond.wait(&self.flow_mutex);
                    }
                    if (self.closed) {
                        self.flow_mutex.unlock();
                        return error.Closed;
                    }
                    const sw = self.stream_windows.get(stream_id) orelse self.peer_initial_window;
                    var allow = @min(self.conn_window, sw);
                    if (allow > @as(i64, @intCast(max_frame_payload))) allow = max_frame_payload;
                    if (allow > @as(i64, @intCast(bytes.len - sent))) allow = @intCast(bytes.len - sent);
                    if (allow <= 0) {
                        self.flow_mutex.unlock();
                        continue;
                    }
                    allowance = @intCast(allow);
                    self.conn_window -= allow;
                    self.stream_windows.put(stream_id, sw - allow) catch {};
                    self.flow_mutex.unlock();
                    try self.writeFrame(h2_data, 0, stream_id, bytes[sent .. sent + allowance]);
                    sent += allowance;
                }
            },
            wire.frameHalfClose => {
                try self.writeFrame(h2_data, flag_end_stream, stream_id, "");
            },
            wire.frameRst => {
                try self.writeFrame(h2_rst_stream, 0, stream_id, &.{ 0, 0, 0, 8 });
            },
            else => {},
        }
    }

    fn recvFn(ctx: *anyopaque, alloc: std.mem.Allocator) anyerror!?[]u8 {
        const self: *Http2Transport = @ptrCast(@alignCast(ctx));
        _ = alloc; // messages were copied with the transport allocator
        self.queue_mutex.lock();
        defer self.queue_mutex.unlock();
        while (self.queue.items.len == 0) {
            if (self.queue_closed) return null;
            self.queue_cond.wait(&self.queue_mutex);
        }
        return self.queue.orderedRemove(0);
    }

    fn closeFn(ctx: *anyopaque) void {
        const self: *Http2Transport = @ptrCast(@alignCast(ctx));
        self.close();
    }

    pub fn close(self: *Http2Transport) void {
        self.markClosed();
        if (self.socket_closed) return;
        self.socket_closed = true;
        self.stream.close();
        self.queue_mutex.lock();
        self.queue_closed = true;
        self.queue_cond.broadcast();
        self.queue_mutex.unlock();
    }

    pub fn deinit(self: *Http2Transport) void {
        self.close();
        if (self.reader_thread) |t| t.join();
        self.decoder.deinit(self.alloc);
        self.stream_windows.deinit();
        var dit = self.data_buffers.valueIterator();
        while (dit.next()) |v| v.deinit(self.alloc);
        self.data_buffers.deinit();
        var hit = self.header_blocks.valueIterator();
        while (hit.next()) |v| v.deinit(self.alloc);
        self.header_blocks.deinit();
        self.headers_seen.deinit();
        self.compress_out.deinit();
        self.decompress_in.deinit();
        for (self.queue.items) |item| self.alloc.free(item);
        self.queue.deinit(self.alloc);
        self.recv_buffer.deinit(self.alloc);
        self.alloc.destroy(self);
    }
};
